insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('commerce.overview','مدیریت فروشگاه','اینجا محصولات، دسته‌ها، موجودی و سفارش‌های سایت را مدیریت می‌کنی. این بخش فقط وقتی قرارداد Commerce برای مشتری فعال باشد قابل استفاده است.',null,'Commerce management','Manage products, categories, inventory and orders here. This area is available only when Commerce is enabled for the tenant contract.',null,true),
('commerce.product','ساخت محصول','محصول ابتدا Draft ساخته می‌شود. نام، آدرس انگلیسی، قیمت و موجودی را وارد کن و بعد از بررسی آن را Published کن.','قبل از انتشار قیمت و موجودی را دوباره بررسی کن.','Create product','Products start as Draft. Enter name, slug, price and stock, review them, then publish.','Recheck price and inventory before publishing.',true),
('commerce.category','دسته‌بندی محصول','دسته‌ها برای مرتب‌کردن محصولات و ساخت صفحه‌های Collection استفاده می‌شوند.',null,'Product category','Categories organize products and power collection pages.',null,true),
('commerce.orders','سفارش‌ها','سفارش‌های مشتری و وضعیت پرداخت از این قسمت دیده می‌شوند. اتصال درگاه پرداخت در لایه جدا انجام می‌شود.','وضعیت Paid فقط باید بعد از تأیید معتبر درگاه ثبت شود.','Orders','Customer orders and payment state appear here. Payment gateways are connected through a separate adapter layer.','Paid status must only be set after verified gateway confirmation.',true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values
('commerce.first-store','commerce','/admin/commerce','راه‌اندازی اولین فروشگاه','از ساخت دسته تا انتشار محصول و دریافت سفارش','۱) اگر لازم است دسته بساز. ۲) محصول را با قیمت و موجودی صحیح به‌صورت Draft ایجاد کن. ۳) اطلاعات را بررسی و Published کن. ۴) سفارش‌ها در همین بخش دیده می‌شوند. ۵) درگاه پرداخت جداگانه متصل می‌شود و فقط نتیجه تأییدشده درگاه می‌تواند سفارش را Paid کند.','Launch your first store','From categories to products and orders','1) Create categories when useful. 2) Create products as Draft with correct price and stock. 3) Review and publish. 4) Orders appear in Commerce. 5) Payment is connected separately and only verified gateway callbacks may mark an order Paid.',array['فروشگاه','محصول','سفارش','موجودی','commerce','product','order','inventory'],'important',array['commerce.overview','commerce.product','commerce.orders'],true,20)
